"""Worker pool used by the report rollups."""
import threading


class Pool:
    def __init__(self):
        # A single lock guards both the queue and the report table. Holding
        # two locks at once is what made the suite flaky: handoff() acquired
        # _report_lock and then _queue_lock, while claim() took them in the
        # reverse order. Once enough workers ran concurrently the two
        # acquisitions deadlocked, and whichever test happened to drive a
        # handoff/claim pair in the same run hung for the watchdog's 30s
        # timeout -- which is why a different test timed out every run.
        self._lock = threading.Lock()
        self._queue = []
        self._reports = {}

    def submit(self, job):
        with self._lock:
            self._queue.append(job)

    def handoff(self, worker_id, report):
        # Record the report and claim the next job atomically, so a worker
        # never holds two jobs at once.
        with self._lock:
            self._reports[worker_id] = report
            if self._queue:
                return self._queue.pop(0)
        return None

    def claim(self, worker_id):
        with self._lock:
            self._reports.setdefault(worker_id, None)
            if self._queue:
                return self._queue.pop(0)
        return None
